// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/typescript.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Primeros pasos con TypeScript", "t": "Qué es TypeScript", "x": "Lenguaje que añade tipos a JavaScript y detecta errores antes de ejecutar.\n\nTypeScript es un superconjunto de JavaScript: todo JavaScript válido también lo es. Los tipos solo existen al programar; al final el código se convierte en JavaScript normal.", "u": "Encontrar errores mientras escribes el código.\n\nTu proyecto JavaScript tiene errores por pasar texto donde iba un número y quieres detectarlos antes de ejecutar.", "p": ["TypeScript añade tipos a JavaScript.", "Todo código JavaScript válido es TypeScript válido.", "Los tipos se eliminan al compilar a JavaScript."], "c": "const edad: number = 20;   // el tipo number detecta errores antes de ejecutar\nconsole.log(\"Edad:\", edad);", "h": "Guarda una edad con tipo number y la muestra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: TypeScript es JavaScript con ___. (5 letras: tipos)", "e": "Creer que los tipos de TypeScript existen al ejecutar el programa."},
  {"m": "Primeros pasos con TypeScript", "t": "Compilar con tsc", "x": "Paso que convierte el código TypeScript en JavaScript.\n\nEl compilador tsc lee los archivos .ts, revisa los tipos y genera archivos .js. Si hay errores de tipos te los muestra, y según la configuración puede generar el JS igualmente.", "u": "Obtener un archivo que el navegador o Node puedan ejecutar.\n\nEscribiste un archivo .ts y el navegador no lo entiende.", "p": ["tsc compila TypeScript a JavaScript.", "El compilador revisa los tipos y muestra errores.", "Los archivos de TypeScript terminan en .ts."], "c": "// En la terminal:  tsc hola.ts   -> crea hola.js\nconst mensaje: string = \"Compilado con tsc\";\nconsole.log(mensaje);", "h": "Muestra un mensaje que luego se compilaría con tsc.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El compilador de TypeScript se llama ___. (3 letras)", "e": "Intentar ejecutar un archivo .ts directamente en el navegador."},
  {"m": "Primeros pasos con TypeScript", "t": "console.log", "x": "Función que muestra valores en la consola.\n\nconsole.log acepta uno o varios valores separados por comas y los imprime. Es la herramienta más rápida para comprobar qué vale una variable.", "u": "Ver resultados y depurar mientras programas.\n\nQuieres ver el valor de una variable mientras pruebas tu programa.", "p": ["console.log muestra valores en la consola.", "console.log acepta varios valores separados por comas.", "console.log ayuda a depurar el código."], "c": "const nombre: string = \"Ana\";\nconsole.log(\"Hola\", nombre);   // muestra: Hola Ana", "h": "Muestra un saludo con el nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que escribe en la consola es console.___. (3 letras)", "e": "Olvidar los paréntesis al llamar a console.log."},
  {"m": "Primeros pasos con TypeScript", "t": "Anotaciones de tipo", "x": "Dos puntos y un tipo escritos después del nombre de una variable.\n\nLa forma es nombre: tipo. Si luego asignas un valor de otro tipo, TypeScript marca error. Así se evitan mezclas como sumar un texto con un número sin querer.", "u": "Decir qué clase de valor guarda una variable.\n\nQuieres dejar claro que la variable precio solo guardará números.", "p": ["Una anotación de tipo se escribe con dos puntos.", "La anotación indica qué valores acepta la variable.", "Asignar un valor de otro tipo produce un error."], "c": "let precio: number = 9.5;   // : number es la anotación\nprecio = 12;\nconsole.log(precio);", "h": "Declara precio como número y cambia su valor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La anotación de tipo usa el signo ___ después del nombre. (:)", "e": "Asignar un texto a una variable declarada como number. edad es number y no puede recibir un texto."},
  {"m": "Primeros pasos con TypeScript", "t": "number", "x": "Tipo para todos los números, enteros o decimales.\n\nTypeScript usa un solo tipo number para enteros y decimales. También incluye valores como Infinity y NaN. Permite operar con +, -, * y /.", "u": "Guardar cantidades y hacer cálculos.\n\nDebes guardar el precio de un producto con decimales.", "p": ["number guarda enteros y decimales.", "number permite hacer cálculos aritméticos.", "NaN también es un valor de tipo number."], "c": "const precio: number = 19.99;\nconst cantidad: number = 3;\nconsole.log(precio * cantidad);   // 59.97", "h": "Multiplica un precio por una cantidad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo para los números es ___. (6 letras)", "e": "Creer que hay un tipo distinto para enteros y decimales."},
  {"m": "Primeros pasos con TypeScript", "t": "string", "x": "Tipo para guardar texto.\n\nUn string se escribe entre comillas simples, dobles o invertidas. Tiene propiedades útiles como length y métodos como toUpperCase.", "u": "Trabajar con nombres, mensajes y palabras.\n\nNecesitas guardar el nombre de un usuario.", "p": ["string guarda texto.", "Un string se escribe entre comillas.", "string tiene la propiedad length."], "c": "const nombre: string = \"Luis\";\nconsole.log(nombre.toUpperCase());   // LUIS\nconsole.log(nombre.length);          // 4", "h": "Muestra el nombre en mayúsculas y su longitud.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo para guardar texto es ___. (6 letras)", "e": "Escribir un texto sin comillas."},
  {"m": "Primeros pasos con TypeScript", "t": "boolean", "x": "Tipo con solo dos valores: true y false.\n\nUn boolean guarda verdadero o falso. Es el resultado de las comparaciones y lo que usan if y while para decidir.", "u": "Representar un sí o un no.\n\nQuieres guardar si un usuario ya activó su cuenta (sí o no).", "p": ["boolean solo admite true o false.", "Las comparaciones dan un resultado boolean.", "if usa un boolean para decidir."], "c": "const activo: boolean = true;\nconst esMayor: boolean = 20 >= 18;   // resultado de comparar\nconsole.log(activo, esMayor);", "h": "Guarda dos valores verdadero/falso y los muestra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo que solo vale true o false es ___. (7 letras)", "e": "Escribir True con mayúscula inicial."},
  {"m": "Primeros pasos con TypeScript", "t": "Inferencia de tipos", "x": "Capacidad de TypeScript de deducir el tipo sin que lo escribas.\n\nSi inicializas una variable con un valor, TypeScript deduce su tipo. Con let ciudad = \"Quito\" ya sabe que es string y no deja asignarle un número después.", "u": "Escribir menos código manteniendo la seguridad de tipos.\n\nNo quieres escribir el tipo en cada variable porque TypeScript ya lo adivina.", "p": ["La inferencia deduce el tipo a partir del valor.", "Una variable inferida también protege contra errores.", "Se puede omitir la anotación cuando el valor ya lo deja claro."], "c": "let ciudad = \"Quito\";   // TypeScript infiere: string\nciudad = \"Lima\";\nconsole.log(ciudad);", "h": "Declara una variable sin tipo explícito y cambia su valor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Cuando TypeScript deduce el tipo sin que lo escribas hay ___ de tipos. (9 letras)", "e": "Pensar que una variable sin anotación acepta cualquier tipo."},
  {"m": "Primeros pasos con TypeScript", "t": "let y const", "x": "Palabras para declarar variables que cambian (let) o no cambian (const).\n\nconst impide reasignar la variable y es la opción por defecto. let se usa cuando el valor va a cambiar. Evita var, que tiene reglas de alcance confusas.", "u": "Elegir si el valor de una variable puede reasignarse.\n\nDeclaras el valor de pi, que nunca debe cambiar.", "p": ["const declara variables que no se reasignan.", "let declara variables que pueden cambiar.", "Conviene usar const por defecto."], "c": "const pi: number = 3.14;   // no se puede reasignar\nlet contador: number = 0;   // sí puede cambiar\ncontador = contador + 1;\nconsole.log(pi, contador);", "h": "Declara una constante y un contador que aumenta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para una variable que no cambia se usa ___. (5 letras)", "e": "Reasignar una variable declarada con const. total es const y no se puede reasignar."},
  {"m": "Primeros pasos con TypeScript", "t": "Plantillas de texto", "x": "Textos entre comillas invertidas que permiten insertar valores con ${}.\n\nCon comillas invertidas puedes escribir ${expresión} dentro del texto y se sustituye por su valor. También permiten varias líneas sin trucos.", "u": "Construir mensajes mezclando texto y variables.\n\nQuieres armar el mensaje «Hola Ana, tienes 20 años» con variables sin sumar textos a mano.", "p": ["Las plantillas de texto usan comillas invertidas.", "${} inserta un valor dentro del texto.", "Una plantilla puede ocupar varias líneas."], "c": "const nombre: string = \"Ana\";\nconst edad: number = 20;\nconsole.log(`Hola ${nombre}, tienes ${edad} años`);   // usa comillas invertidas", "h": "Arma un saludo con el nombre y la edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Dentro de una plantilla de texto los valores van en ${ ___ }. (una expresión)", "e": "Usar comillas normales y esperar que ${} funcione. Con comillas normales ${n} no se sustituye; hacen falta comillas invertidas."},
  {"m": "Primeros pasos con TypeScript", "t": "any", "x": "Tipo que desactiva la revisión de tipos para un valor.\n\nUn valor any acepta cualquier cosa y TypeScript no lo comprueba. Es práctico al migrar código viejo, pero anula la protección, así que conviene evitarlo.", "u": "Salir del paso con datos de tipo desconocido (con cuidado).\n\nEstás migrando código antiguo y no conoces el tipo de un dato, solo quieres que compile por ahora.", "p": ["any desactiva la revisión de tipos.", "Un valor any acepta cualquier cosa.", "Usar mucho any elimina la ventaja de TypeScript."], "c": "let dato: any = 5;   // any: sin revisión\ndato = \"ahora soy texto\";\nconsole.log(dato);", "h": "Guarda primero un número y luego un texto en la misma variable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo que desactiva la revisión de tipos es ___. (3 letras)", "e": "Usar any por costumbre en todas partes."},
  {"m": "Primeros pasos con TypeScript", "t": "unknown", "x": "Tipo seguro para valores cuyo tipo aún no se conoce.\n\nA diferencia de any, con unknown no puedes usar el valor hasta comprobar su tipo, por ejemplo con typeof. Es la opción segura para datos externos.", "u": "Recibir datos desconocidos obligando a comprobarlos antes de usarlos.\n\nRecibes un dato de una fuente externa y quieres obligarte a verificar su tipo antes de usarlo.", "p": ["unknown obliga a comprobar el tipo antes de usar el valor.", "unknown es más seguro que any.", "typeof sirve para acotar un valor unknown."], "c": "let valor: unknown = \"hola\";\nif (typeof valor === \"string\") {   // se comprueba antes de usar\n  console.log(valor.toUpperCase());\n}", "h": "Comprueba que el valor es texto antes de pasarlo a mayúsculas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo seguro para datos desconocidos es ___. (7 letras)", "e": "Usar un valor unknown sin comprobar su tipo antes."},
  {"m": "Primeros pasos con TypeScript", "t": "null y undefined", "x": "Valores especiales que representan «sin valor» y «sin asignar».\n\nundefined significa que la variable no tiene valor asignado; null significa vacío a propósito. Con strict activado, un number no puede ser null salvo que lo declares como number | null.", "u": "Indicar la ausencia de un dato.\n\nUna variable aún no recibió ningún valor y quieres reflejarlo.", "p": ["undefined significa que no se asignó ningún valor.", "null representa un valor vacío a propósito.", "Con strict un number no puede ser null sin declararlo."], "c": "let apodo: string | undefined;   // aún sin valor\nconsole.log(apodo);                // undefined\napodo = \"Pepe\";\nconsole.log(apodo);", "h": "Muestra una variable sin valor y luego con valor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable declarada sin valor es ___. (9 letras)", "e": "Confundir null con undefined."},
  {"m": "Primeros pasos con TypeScript", "t": "Arrays tipados", "x": "Listas donde todos los elementos son del mismo tipo.\n\nSe escriben como number[] o Array<number>. TypeScript no deja añadir un elemento de otro tipo. Se accede por posición empezando en 0.", "u": "Guardar varios valores del mismo tipo juntos.\n\nQuieres guardar una lista de notas, todas numéricas.", "p": ["Un array tipado guarda elementos del mismo tipo.", "Se escribe como number[] o Array<number>.", "El primer elemento está en la posición 0."], "c": "const notas: number[] = [7, 9, 8];   // lista de números\nnotas.push(10);\nconsole.log(notas.length, notas[0]);", "h": "Crea una lista de notas, añade una y muestra su tamaño y la primera.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un array de números se escribe number___. ([])", "e": "Añadir a un array de números un elemento de texto. notas solo admite números, no texto."},
  {"m": "Primeros pasos con TypeScript", "t": "Tuplas", "x": "Arrays de longitud fija con un tipo para cada posición.\n\nUna tupla como [string, number] exige un texto primero y un número después. Es útil para pares como nombre y edad.", "u": "Agrupar pocos valores de tipos distintos en orden fijo.\n\nQuieres guardar un par fijo: primero el nombre y después la edad.", "p": ["Una tupla tiene longitud fija.", "Cada posición de una tupla tiene su propio tipo.", "Las tuplas se escriben con corchetes y tipos distintos."], "c": "const persona: [string, number] = [\"Ana\", 20];   // texto y número, en ese orden\nconsole.log(persona[0], persona[1]);", "h": "Guarda un nombre y una edad en una tupla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un array de longitud fija con tipos por posición es una ___. (5 letras)", "e": "Poner los elementos de una tupla en distinto orden que sus tipos."},
  {"m": "Primeros pasos con TypeScript", "t": "enum", "x": "Conjunto de constantes con nombre.\n\nUn enum agrupa opciones como Direccion.Arriba o Direccion.Abajo. Por defecto se numeran desde 0, pero también pueden ser textos.", "u": "Dar nombres legibles a un grupo de valores relacionados.\n\nTu programa usa los estados «pendiente», «activo» y «cerrado» y no quieres escribirlos a mano cada vez.", "p": ["Un enum agrupa constantes con nombre.", "Por defecto los miembros de un enum se numeran desde 0.", "Un enum evita usar números o textos sueltos."], "c": "enum Estado { Pendiente, Activo, Cerrado }   // 0, 1, 2\nconst actual: Estado = Estado.Activo;\nconsole.log(actual, Estado[actual]);", "h": "Define tres estados y muestra el actual.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para definir un grupo de constantes con nombre es ___. (4 letras)", "e": "Escribir el valor numérico a mano en lugar de usar el nombre del enum."},
  {"m": "Primeros pasos con TypeScript", "t": "Operador ===", "x": "Comparación estricta que revisa valor y tipo.\n\n=== devuelve true solo si valor y tipo son iguales. == convierte tipos antes de comparar y da resultados raros como 0 == \"\". En TypeScript se recomienda siempre ===.", "u": "Comparar sin conversiones sorprendentes.\n\nQuieres comparar dos valores sin que JavaScript convierta tipos por su cuenta.", "p": ["=== compara valor y tipo.", "== convierte tipos y puede sorprender.", "Se recomienda usar === siempre."], "c": "console.log(5 === 5);       // true\nconsole.log(\"5\" === \"5\");   // true\nconsole.log(5 === Number(\"6\"));   // false: valores distintos", "h": "Compara valores con igualdad estricta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de igualdad estricta tiene ___ signos igual. (un número)", "e": "Usar == y confiar en la conversión automática."},
  {"m": "Primeros pasos con TypeScript", "t": "if y else", "x": "Estructura que ejecuta código solo si se cumple una condición.\n\nif evalúa una condición entre paréntesis. Si es verdadera ejecuta su bloque; si no, ejecuta el bloque de else. Se pueden encadenar con else if.", "u": "Tomar decisiones en el programa.\n\nDebes mostrar «Mayor» si la edad es 18 o más y «Menor» en caso contrario.", "p": ["if ejecuta código solo si la condición es verdadera.", "else se ejecuta cuando la condición es falsa.", "else if permite encadenar varias condiciones."], "c": "const edad: number = 20;\nif (edad >= 18) {\n  console.log(\"Mayor\");   // si se cumple\n} else {\n  console.log(\"Menor\");   // si no se cumple\n}", "h": "Muestra Mayor o Menor según la edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para el caso contrario de un if es ___. (4 letras)", "e": "Olvidar las llaves o los paréntesis de la condición."},
  {"m": "Primeros pasos con TypeScript", "t": "Bucle for", "x": "Estructura que repite un bloque un número conocido de veces.\n\nfor tiene tres partes: inicio, condición y paso, separadas por punto y coma. También existe for...of para recorrer los elementos de un array directamente.", "u": "Recorrer rangos o listas paso a paso.\n\nQuieres mostrar los números del 1 al 5 sin escribir cinco veces el mismo código.", "p": ["for repite un bloque varias veces.", "for tiene inicio, condición y paso.", "for...of recorre los elementos de un array."], "c": "for (let i = 1; i <= 5; i++) {   // inicio; condición; paso\n  console.log(\"Vuelta\", i);\n}", "h": "Muestra las vueltas del 1 al 5.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que repite con inicio, condición y paso es ___. (3 letras)", "e": "Crear un bucle cuya condición nunca deja de cumplirse."},
  {"m": "Primeros pasos con TypeScript", "t": "Comentarios", "x": "Texto del código que el compilador ignora.\n\n// comenta una línea y /* ... */ comenta varias. Un buen comentario explica el porqué, no repite lo que ya dice el código.", "u": "Explicar el código a quien lo lea.\n\nQuieres dejar una nota sobre por qué hiciste un cálculo sin que afecte al programa.", "p": ["Los comentarios son ignorados al compilar.", "// comenta una sola línea.", "/* */ permite comentar varias líneas."], "c": "// Esto es un comentario de una línea\n/* Y este\n   ocupa varias líneas */\nconsole.log(\"Los comentarios no se ejecutan\");", "h": "Muestra un mensaje; los comentarios no se ejecutan.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El comentario de una línea empieza con ___. (//)", "e": "Comentar lo obvio en lugar de explicar el motivo."},
  {"m": "Funciones, objetos e interfaces", "t": "Funciones tipadas", "x": "Funciones cuyos parámetros llevan un tipo.\n\nCada parámetro se escribe como nombre: tipo. Si llamas a la función con otro tipo o con argumentos de más o de menos, TypeScript lo marca como error.", "u": "Evitar llamar a una función con datos incorrectos.\n\nQuieres que una función de suma solo acepte números y no textos.", "p": ["Una función tipada declara el tipo de cada parámetro.", "TypeScript rechaza llamadas con tipos incorrectos.", "También se comprueba la cantidad de argumentos."], "c": "function sumar(a: number, b: number) {   // parámetros con tipo\n  return a + b;\n}\nconsole.log(sumar(2, 3));", "h": "Suma dos números con una función tipada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los parámetros de una función se tipan con nombre___ tipo. (:)", "e": "Llamar a una función con un texto donde espera un número. doble espera un number, no un texto."},
  {"m": "Funciones, objetos e interfaces", "t": "Tipo de retorno", "x": "Tipo del valor que devuelve una función, escrito después de los paréntesis.\n\nSe escribe con dos puntos tras los paréntesis: function f(): string. Si algún camino devuelve otro tipo, TypeScript avisa. Normalmente puede inferirse, pero escribirlo documenta la función.", "u": "Asegurar que la función devuelve lo prometido.\n\nQuieres garantizar que una función siempre devuelva un texto.", "p": ["El tipo de retorno se escribe después de los paréntesis.", "TypeScript comprueba lo que devuelve la función.", "El tipo de retorno documenta la función."], "c": "function saludar(nombre: string): string {   // devuelve un string\n  return \"Hola \" + nombre;\n}\nconsole.log(saludar(\"Ana\"));", "h": "Devuelve un saludo con el nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de retorno va después de los ___. (paréntesis)", "e": "Devolver un tipo distinto al declarado."},
  {"m": "Funciones, objetos e interfaces", "t": "void", "x": "Tipo de retorno de funciones que no devuelven ningún valor.\n\nvoid se usa en funciones que muestran, guardan o modifican algo sin devolver un resultado. Una función void no debe usarse para asignar su resultado a una variable.", "u": "Indicar que una función solo hace una acción.\n\nTu función solo imprime un mensaje y no devuelve nada.", "p": ["void indica que la función no devuelve un valor.", "Se usa en funciones que solo realizan una acción.", "No se debe usar el resultado de una función void."], "c": "function avisar(msg: string): void {   // no devuelve nada\n  console.log(\"Aviso:\", msg);\n}\navisar(\"Guardado\");", "h": "Muestra un aviso sin devolver valor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de una función que no devuelve nada es ___. (4 letras)", "e": "Intentar usar el resultado de una función void."},
  {"m": "Funciones, objetos e interfaces", "t": "Parámetros opcionales", "x": "Parámetros marcados con ? que pueden omitirse al llamar.\n\nUn parámetro con ? puede faltar y entonces vale undefined. Los opcionales deben ir al final de la lista de parámetros.", "u": "Permitir llamadas con menos argumentos.\n\nQuieres que el apellido pueda omitirse al llamar a la función.", "p": ["Un parámetro opcional se marca con ?.", "Si se omite, el parámetro vale undefined.", "Los opcionales van después de los obligatorios."], "c": "function saludar(nombre: string, apellido?: string) {   // ? lo hace opcional\n  console.log(apellido ? nombre + \" \" + apellido : nombre);\n}\nsaludar(\"Ana\");\nsaludar(\"Ana\", \"Pérez\");", "h": "Saluda con o sin apellido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro opcional se marca con el signo ___. (?)", "e": "Poner un parámetro opcional antes de uno obligatorio. Un parámetro opcional no puede ir antes de uno obligatorio."},
  {"m": "Funciones, objetos e interfaces", "t": "Valores por defecto", "x": "Valor que toma un parámetro cuando no se envía ninguno.\n\nSe escribe con = después del parámetro. Si llamas sin ese argumento (o con undefined), se usa el valor por defecto. El tipo se infiere del valor.", "u": "Evitar comprobar si falta un argumento.\n\nSi no se indica el saludo, quieres que se use «Hola» automáticamente.", "p": ["Un valor por defecto se escribe con = en el parámetro.", "Se usa cuando se omite el argumento.", "El tipo se infiere del valor por defecto."], "c": "function saludar(nombre: string, saludo: string = \"Hola\") {   // valor por defecto\n  console.log(saludo, nombre);\n}\nsaludar(\"Ana\");", "h": "Saluda con «Hola» cuando no se indica otro saludo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor por defecto de un parámetro se asigna con el signo ___. (=)", "e": "Creer que el valor por defecto reemplaza un argumento enviado."},
  {"m": "Funciones, objetos e interfaces", "t": "Parámetros rest", "x": "Parámetro con ... que agrupa los argumentos sobrantes en un array.\n\n...nombre: tipo[] recoge todos los argumentos restantes en un array. Solo puede haber uno y debe ser el último parámetro.", "u": "Aceptar una cantidad variable de argumentos.\n\nQuieres una función que sume cualquier cantidad de números.", "p": ["Un parámetro rest se escribe con tres puntos.", "Agrupa los argumentos sobrantes en un array.", "Debe ser el último parámetro."], "c": "function sumar(...nums: number[]): number {   // recoge todos en un array\n  return nums.reduce((a, b) => a + b, 0);\n}\nconsole.log(sumar(1, 2, 3, 4));", "h": "Suma todos los números recibidos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro rest empieza con ___ puntos. (un número)", "e": "Poner el parámetro rest antes de otros parámetros."},
  {"m": "Funciones, objetos e interfaces", "t": "Funciones flecha", "x": "Forma corta de escribir funciones con =>.\n\n(a, b) => a + b equivale a una función completa. Si el cuerpo es una sola expresión, el return es implícito. Heredan el this del contexto donde se crean.", "u": "Escribir funciones breves y callbacks.\n\nNecesitas pasar una función breve que duplique cada número de una lista.", "p": ["Las funciones flecha se escriben con =>.", "Con una sola expresión el return es implícito.", "Una flecha hereda el this de su contexto."], "c": "const doble = (n: number): number => n * 2;   // flecha con retorno implícito\nconsole.log([1, 2, 3].map(doble));", "h": "Duplica cada número de una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo de una función flecha es ___. (=>)", "e": "Olvidar las llaves y el return cuando el cuerpo tiene varias líneas."},
  {"m": "Funciones, objetos e interfaces", "t": "Tipos de función", "x": "Tipo que describe los parámetros y el retorno de una función.\n\nSe escribe como (a: number, b: number) => number. Sirve para decir qué forma debe tener una función que se pasa como argumento (callback).", "u": "Tipar variables o parámetros que contienen funciones.\n\nRecibes una función como parámetro y quieres exigir que reciba un número y devuelva un texto.", "p": ["Un tipo de función describe parámetros y retorno.", "Se usa para tipar callbacks.", "Se escribe con una flecha entre parámetros y retorno."], "c": "type Formato = (n: number) => string;   // forma de la función\nconst aTexto: Formato = (n) => \"Nº \" + n;\nconsole.log(aTexto(7));", "h": "Define y usa un tipo para funciones que convierten números en texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un tipo de función separa parámetros y retorno con ___. (=>)", "e": "Pasar una función con otra firma de la esperada."},
  {"m": "Funciones, objetos e interfaces", "t": "Objetos tipados", "x": "Objetos cuya forma de propiedades y tipos está declarada.\n\nSe escribe { nombre: string; edad: number }. TypeScript revisa que el objeto tenga todas las propiedades y que cada una sea del tipo correcto.", "u": "Describir qué datos tiene un objeto.\n\nQuieres asegurar que un objeto persona siempre tenga nombre y edad.", "p": ["Un objeto tipado declara sus propiedades y tipos.", "TypeScript revisa que no falte ninguna propiedad.", "Cada propiedad debe ser del tipo declarado."], "c": "const persona: { nombre: string; edad: number } = {   // forma del objeto\n  nombre: \"Ana\",\n  edad: 20,\n};\nconsole.log(persona.nombre, persona.edad);", "h": "Crea un objeto persona con nombre y edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Se accede a una propiedad de un objeto con ___ y su nombre. (un punto)", "e": "Olvidar una propiedad obligatoria del objeto. Falta la propiedad obligatoria edad."},
  {"m": "Funciones, objetos e interfaces", "t": "Propiedades opcionales", "x": "Propiedades de objeto marcadas con ? que pueden no existir.\n\nEn un tipo, nombre?: string indica que la propiedad puede faltar. Al leerla, su tipo incluye undefined, así que conviene comprobarla.", "u": "Describir datos que a veces faltan.\n\nEl teléfono del usuario es opcional: algunos lo tienen y otros no.", "p": ["Una propiedad opcional se marca con ? tras su nombre.", "Si falta, su valor es undefined.", "Conviene comprobar una propiedad opcional antes de usarla."], "c": "type Usuario = { nombre: string; telefono?: string };   // telefono es opcional\nconst u: Usuario = { nombre: \"Ana\" };\nconsole.log(u.telefono ?? \"sin teléfono\");", "h": "Muestra el teléfono o «sin teléfono» si falta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una propiedad opcional se marca con ___ antes de los dos puntos. (?)", "e": "Usar una propiedad opcional sin comprobar que existe."},
  {"m": "Funciones, objetos e interfaces", "t": "readonly", "x": "Modificador que impide cambiar una propiedad después de crearla.\n\nUna propiedad readonly solo se asigna al crear el objeto. Intentar cambiarla después produce un error de compilación.", "u": "Proteger datos que no deben modificarse.\n\nEl id de un usuario no debe cambiar jamás después de crearse.", "p": ["readonly impide modificar una propiedad.", "Solo se puede asignar al crear el objeto.", "El error aparece al compilar."], "c": "type Usuario = { readonly id: number; nombre: string };   // id no se puede cambiar\nconst u: Usuario = { id: 1, nombre: \"Ana\" };\nu.nombre = \"Eva\";\nconsole.log(u);", "h": "Cambia el nombre pero deja el id protegido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modificador que impide cambiar una propiedad es ___. (8 letras)", "e": "Intentar reasignar una propiedad readonly. id es readonly y no se puede reasignar."},
  {"m": "Funciones, objetos e interfaces", "t": "Alias de tipo", "x": "Nombre propio que se da a un tipo con la palabra type.\n\ntype Nombre = ... crea un alias que puedes usar en cualquier parte. Sirve para objetos, uniones, funciones y más. No crea un tipo nuevo, solo un nombre.", "u": "Reutilizar un tipo sin repetirlo.\n\nRepites { x: number; y: number } en muchos sitios y quieres darle un nombre.", "p": ["type crea un alias para un tipo.", "Un alias se puede usar en muchos lugares.", "Un alias no crea un tipo nuevo, solo un nombre."], "c": "type Punto = { x: number; y: number };   // alias reutilizable\nconst a: Punto = { x: 1, y: 2 };\nconsole.log(a.x + a.y);", "h": "Define un tipo Punto y lo usa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que crea un alias de tipo es ___. (4 letras)", "e": "Repetir el mismo tipo en muchos lugares en vez de darle un alias."},
  {"m": "Funciones, objetos e interfaces", "t": "Interfaces", "x": "Forma de describir la estructura que debe tener un objeto.\n\ninterface Nombre { ... } declara propiedades y métodos. Es muy parecida a un alias de tipo para objetos, y las interfaces con el mismo nombre se fusionan.", "u": "Definir contratos que los objetos deben cumplir.\n\nQuieres un contrato que todo objeto «Animal» debe cumplir.", "p": ["Una interface describe la forma de un objeto.", "Las interfaces definen contratos.", "Dos interfaces con el mismo nombre se fusionan."], "c": "interface Animal {   // contrato\n  nombre: string;\n  sonido(): string;\n}\nconst perro: Animal = { nombre: \"Rex\", sonido: () => \"Guau\" };\nconsole.log(perro.nombre, perro.sonido());", "h": "Declara una interfaz Animal y crea un perro que la cumple.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para declarar un contrato de objeto es ___. (9 letras)", "e": "Olvidar implementar una propiedad exigida por la interfaz."},
  {"m": "Funciones, objetos e interfaces", "t": "Extender interfaces", "x": "Crear una interfaz nueva a partir de otra con extends.\n\ninterface B extends A copia las propiedades de A y permite añadir más. Se puede extender de varias interfaces separándolas con comas.", "u": "Reutilizar propiedades y añadir las propias.\n\nQuieres un «Empleado» que tenga todo lo de «Persona» y además un sueldo.", "p": ["extends hereda las propiedades de otra interfaz.", "La interfaz nueva puede añadir sus propias propiedades.", "Se puede extender de varias interfaces a la vez."], "c": "interface Persona { nombre: string }\ninterface Empleado extends Persona { sueldo: number }   // hereda nombre\nconst e: Empleado = { nombre: \"Ana\", sueldo: 1500 };\nconsole.log(e.nombre, e.sueldo);", "h": "Crea un empleado que hereda el nombre de Persona.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para heredar propiedades de otra interfaz se usa ___. (7 letras)", "e": "Repetir manualmente las propiedades de la interfaz base."},
  {"m": "Funciones, objetos e interfaces", "t": "Unión de tipos", "x": "Tipo que permite varias alternativas separadas por |.\n\nstring | number acepta texto o número. Para usar métodos de uno solo debes primero comprobar de qué tipo es con typeof.", "u": "Aceptar un valor que puede ser de más de un tipo.\n\nUn identificador puede ser un número o un texto.", "p": ["Una unión se escribe con el símbolo |.", "Una unión acepta cualquiera de sus tipos.", "Hay que acotar el tipo antes de usar métodos específicos."], "c": "let id: string | number = 5;   // puede ser texto o número\nid = \"A-7\";\nconsole.log(id);", "h": "Guarda un id que cambia de número a texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una unión de tipos se separa con la barra ___. (|)", "e": "Usar un método de string sobre una unión sin comprobar el tipo."},
  {"m": "Funciones, objetos e interfaces", "t": "Tipos literales", "x": "Tipos que aceptan solo valores exactos concretos.\n\nEn lugar de string puedes escribir \"norte\" | \"sur\" | \"este\". Solo se aceptarán esos valores y el editor los sugiere.", "u": "Limitar una variable a unas pocas opciones permitidas.\n\nUna variable solo debe valer «norte», «sur», «este» u «oeste».", "p": ["Un tipo literal acepta solo valores concretos.", "Se combinan con | para listar opciones.", "El editor autocompleta las opciones permitidas."], "c": "type Direccion = \"norte\" | \"sur\" | \"este\" | \"oeste\";   // opciones exactas\nconst d: Direccion = \"norte\";\nconsole.log(d);", "h": "Restringe una dirección a cuatro valores posibles.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un tipo que solo acepta un valor exacto se llama tipo ___. (7 letras)", "e": "Asignar un valor que no está en la lista del tipo literal. «verde» no está entre los valores permitidos."},
  {"m": "Funciones, objetos e interfaces", "t": "Intersección de tipos", "x": "Tipo que combina varios tipos con &.\n\nA & B exige que el valor cumpla A y B a la vez. Se usa para mezclar objetos pequeños en uno más completo.", "u": "Juntar propiedades de varios tipos en uno.\n\nQuieres un tipo que reúna a la vez las propiedades de «Nombre» y de «Edad».", "p": ["Una intersección se escribe con el símbolo &.", "El valor debe cumplir todos los tipos combinados.", "Sirve para juntar propiedades de varios tipos."], "c": "type ConNombre = { nombre: string };\ntype ConEdad = { edad: number };\nconst p: ConNombre & ConEdad = { nombre: \"Ana\", edad: 20 };   // cumple ambos\nconsole.log(p);", "h": "Combina dos tipos en un objeto completo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La intersección de tipos se escribe con el signo ___. (&)", "e": "Confundir & (ambos) con | (alguno)."},
  {"m": "Funciones, objetos e interfaces", "t": "Acotar con typeof", "x": "Comprobación del tipo de un valor para que TypeScript lo reconozca.\n\nDentro de if (typeof x === \"string\"), TypeScript sabe que x es string. A ese proceso se le llama acotar o estrechar el tipo (narrowing).", "u": "Usar con seguridad valores de tipo unión.\n\nRecibes un valor que puede ser texto o número y debes tratar cada caso por separado.", "p": ["typeof comprueba el tipo de un valor.", "Tras comprobar, TypeScript conoce el tipo exacto.", "Acotar el tipo se llama narrowing."], "c": "function mostrar(v: string | number) {\n  if (typeof v === \"string\") console.log(v.toUpperCase());   // aquí v es string\n  else console.log(v.toFixed(1));                           // aquí v es number\n}\nmostrar(\"hola\");\nmostrar(3);", "h": "Trata distinto un texto y un número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que revisa el tipo de un valor es ___. (6 letras)", "e": "Usar métodos de un tipo sin comprobar antes."},
  {"m": "Funciones, objetos e interfaces", "t": "Aserción de tipos", "x": "Indicación con as de que sabes más que el compilador sobre un tipo.\n\nvalor as Tipo cambia el tipo solo para el compilador; no convierte nada en tiempo de ejecución. Úsala con cuidado: si te equivocas, el error aparece al ejecutar.", "u": "Decirle a TypeScript el tipo cuando tú lo conoces mejor.\n\nSabes que un valor desconocido es un texto y quieres tratarlo como tal.", "p": ["as indica un tipo al compilador.", "as no convierte el valor en tiempo de ejecución.", "Una aserción incorrecta causa errores al ejecutar."], "c": "const dato: unknown = \"hola\";\nconst largo = (dato as string).length;   // afirmas que es string\nconsole.log(largo);", "h": "Trata un valor desconocido como texto y mide su largo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que afirma un tipo es ___. (2 letras)", "e": "Usar as para convertir datos en lugar de comprobar su tipo."},
  {"m": "Funciones, objetos e interfaces", "t": "?. y ??", "x": "Operadores para acceder a propiedades que pueden faltar y dar valores por defecto.\n\n?. detiene la cadena y devuelve undefined si algo falta. ?? usa el valor de la derecha solo si el de la izquierda es null o undefined; a diferencia de ||, respeta el 0 y el texto vacío.", "u": "Evitar errores con valores null o undefined.\n\nQuieres leer el teléfono de un usuario que quizá no exista y mostrar «sin dato» si falta.", "p": ["?. evita errores al acceder a algo que puede faltar.", "?? da un valor si el de la izquierda es null o undefined.", "?? respeta el 0 y el texto vacío."], "c": "function telefono(u?: { tel?: string }): string {\n  return u?.tel ?? \"sin dato\";   // ?. no falla y ?? da el valor por defecto\n}\nconsole.log(telefono(), telefono({ tel: \"099\" }));", "h": "Muestra «sin dato» cuando falta el usuario o su teléfono.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de acceso opcional es ___. (?.)", "e": "Usar || y perder valores válidos como 0."},
  {"m": "Clases y módulos", "t": "Clases", "x": "Plantilla que define propiedades y métodos de un tipo de objeto.\n\nUna clase se declara con class y se usa con new para crear instancias. Reúne datos (propiedades) y acciones (métodos) en un solo lugar.", "u": "Crear muchos objetos con la misma estructura y comportamiento.\n\nNecesitas crear muchos alumnos con los mismos datos y las mismas acciones.", "p": ["Una clase es una plantilla para crear objetos.", "new crea una instancia de una clase.", "Una clase reúne propiedades y métodos."], "c": "class Alumno {\n  nombre: string = \"Ana\";\n  saludar(): string { return \"Hola, soy \" + this.nombre; }   // método\n}\nconst a = new Alumno();   // instancia\nconsole.log(a.saludar());", "h": "Define una clase Alumno y usa una instancia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para declarar una clase es ___. (5 letras)", "e": "Usar la clase sin crear antes una instancia con new."},
  {"m": "Clases y módulos", "t": "Constructor", "x": "Método especial que se ejecuta al crear una instancia.\n\nSe escribe constructor(...) dentro de la clase. Recibe parámetros y los asigna a this. Solo puede haber uno por clase.", "u": "Inicializar las propiedades del objeto con valores.\n\nCada alumno debe nacer con su nombre y su edad ya asignados.", "p": ["El constructor se ejecuta al crear una instancia.", "El constructor inicializa las propiedades.", "Una clase solo tiene un constructor."], "c": "class Alumno {\n  nombre: string;\n  edad: number;\n  constructor(nombre: string, edad: number) {   // se ejecuta con new\n    this.nombre = nombre;\n    this.edad = edad;\n  }\n}\nconst a = new Alumno(\"Luis\", 20);\nconsole.log(a.nombre, a.edad);", "h": "Crea un alumno con nombre y edad iniciales.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que se ejecuta al crear una instancia es el ___. (11 letras)", "e": "Olvidar asignar los parámetros a this en el constructor."},
  {"m": "Clases y módulos", "t": "this", "x": "Referencia al objeto actual dentro de una clase.\n\nDentro de un método, this apunta a la instancia que lo llama. Sin this, el nombre se busca como una variable local y no como propiedad.", "u": "Acceder a las propiedades y métodos de la propia instancia.\n\nDentro de un método necesitas leer la propiedad nombre del mismo objeto.", "p": ["this representa la instancia actual.", "this permite leer las propiedades del objeto.", "Sin this no se accede a las propiedades de la instancia."], "c": "class Gato {\n  constructor(public nombre: string) {}\n  hablar(): void { console.log(this.nombre + \" dice miau\"); }   // this.nombre\n}\nnew Gato(\"Misu\").hablar();", "h": "Muestra lo que dice un gato usando su nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para referirte al objeto actual dentro de la clase usas ___. (4 letras)", "e": "Olvidar this al leer una propiedad dentro de un método. Debe ser this.n para leer la propiedad."},
  {"m": "Clases y módulos", "t": "public y private", "x": "Modificadores que controlan quién puede usar una propiedad o método.\n\npublic (por defecto) permite acceso desde cualquier lugar. private lo limita a la propia clase. Intentar usar un miembro private desde fuera da error al compilar.", "u": "Ocultar detalles internos de una clase.\n\nEl saldo de una cuenta no debe modificarse directamente desde fuera.", "p": ["public permite acceder desde cualquier lugar.", "private limita el acceso a la propia clase.", "Acceder a un miembro private desde fuera da error."], "c": "class Cuenta {\n  private saldo: number = 100;   // solo se usa dentro de la clase\n  mostrar(): void { console.log(this.saldo); }\n}\nnew Cuenta().mostrar();", "h": "Muestra un saldo guardado como propiedad privada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modificador que oculta un miembro fuera de la clase es ___. (7 letras)", "e": "Acceder a una propiedad private desde fuera de la clase. x es private y no se puede leer desde fuera."},
  {"m": "Clases y módulos", "t": "protected", "x": "Modificador que permite acceso desde la clase y sus hijas.\n\nprotected es un punto medio entre public y private: lo ven la clase y las que heredan de ella, pero no el código externo.", "u": "Compartir miembros con subclases sin exponerlos al exterior.\n\nQuieres que una propiedad la vean las clases hijas pero no el código externo.", "p": ["protected permite acceso a la clase y sus subclases.", "protected no es visible desde fuera de la jerarquía.", "protected es un punto medio entre public y private."], "c": "class Animal {\n  protected energia: number = 10;   // visible para las hijas\n}\nclass Perro extends Animal {\n  correr(): void { console.log(\"Energía:\", this.energia); }\n}\nnew Perro().correr();", "h": "Muestra una propiedad protegida desde una subclase.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modificador visible solo para la clase y sus hijas es ___. (9 letras)", "e": "Confundir protected con private."},
  {"m": "Clases y módulos", "t": "Parámetros-propiedad", "x": "Forma abreviada de declarar y asignar propiedades en el constructor.\n\nSi anteponemos un modificador a un parámetro del constructor, como public nombre: string, TypeScript crea la propiedad y la asigna automáticamente.", "u": "Escribir menos código al crear clases.\n\nEstás cansado de declarar cada propiedad y asignarla en el constructor.", "p": ["Un parámetro-propiedad declara y asigna a la vez.", "Se logra poniendo un modificador al parámetro del constructor.", "Ahorra escribir asignaciones repetidas."], "c": "class Punto {\n  constructor(public x: number, public y: number) {}   // declara y asigna\n}\nconst p = new Punto(2, 3);\nconsole.log(p.x, p.y);", "h": "Crea un punto con propiedades x e y en una sola línea.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro del constructor con un ___ como public crea la propiedad. (modificador)", "e": "Escribir el modificador y además repetir la asignación manualmente."},
  {"m": "Clases y módulos", "t": "readonly en clases", "x": "Propiedad de clase que solo puede asignarse al crear la instancia.\n\nSe puede asignar al declararla o dentro del constructor. Después, cualquier intento de cambiarla produce un error de compilación.", "u": "Evitar que un dato se cambie después de crear el objeto.\n\nEl número de documento de un cliente no debe cambiar tras crearlo.", "p": ["readonly en una clase impide reasignar la propiedad.", "Solo puede asignarse en la declaración o en el constructor.", "Cambiarla después es un error de compilación."], "c": "class Cliente {\n  constructor(public readonly documento: string) {}   // no se reasigna\n}\nconst c = new Cliente(\"123\");\nconsole.log(c.documento);", "h": "Crea un cliente con documento inmutable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad de clase que no se reasigna se marca ___. (8 letras)", "e": "Reasignar una propiedad readonly fuera del constructor."},
  {"m": "Clases y módulos", "t": "Herencia con extends", "x": "Mecanismo por el que una clase hija toma lo de una clase padre.\n\nclass Hija extends Padre hereda propiedades y métodos. La hija puede añadir los suyos o sobrescribir los heredados.", "u": "Reutilizar código entre clases relacionadas.\n\nPerro y Gato comparten comportamientos de Animal y quieres no repetir código.", "p": ["extends crea una clase hija de otra clase.", "La clase hija hereda propiedades y métodos.", "La hija puede sobrescribir métodos del padre."], "c": "class Animal { respirar(): void { console.log(\"respira\"); } }\nclass Perro extends Animal {   // hereda de Animal\n  ladrar(): void { console.log(\"guau\"); }\n}\nconst p = new Perro();\np.respirar();\np.ladrar();", "h": "Un perro usa un método heredado y uno propio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una clase hereda de otra con la palabra ___. (7 letras)", "e": "Repetir código en clases que podrían heredar."},
  {"m": "Clases y módulos", "t": "super", "x": "Palabra que llama al constructor o a los métodos de la clase padre.\n\nEn el constructor de una hija, super(...) debe llamarse antes de usar this. En un método, super.metodo() ejecuta la versión del padre.", "u": "Reutilizar la inicialización o el comportamiento del padre.\n\nUna clase hija necesita ejecutar la inicialización de su padre antes de la suya.", "p": ["super llama al constructor de la clase padre.", "super debe llamarse antes de usar this en el constructor.", "super.metodo() ejecuta el método del padre."], "c": "class Persona { constructor(public nombre: string) {} }\nclass Alumno extends Persona {\n  constructor(nombre: string, public curso: string) {\n    super(nombre);   // llama al constructor del padre\n  }\n}\nconsole.log(new Alumno(\"Ana\", \"TS\"));", "h": "Inicializa el nombre con el constructor del padre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que llama al constructor del padre es ___. (5 letras)", "e": "Usar this antes de llamar a super en el constructor. Hay que llamar a super antes de usar this."},
  {"m": "Clases y módulos", "t": "Clases abstractas", "x": "Clases que sirven de base y no pueden instanciarse directamente.\n\nSe declaran con abstract class. Pueden tener métodos abstractos sin cuerpo que cada hija debe implementar. No se puede hacer new de una clase abstracta.", "u": "Definir una base común que obliga a las hijas a completar métodos.\n\nQuieres una clase base «Figura» que obligue a cada figura a calcular su área, pero que nunca se cree sola.", "p": ["Una clase abstracta no se puede instanciar.", "Los métodos abstractos no tienen cuerpo.", "Las clases hijas deben implementar los métodos abstractos."], "c": "abstract class Figura {\n  abstract area(): number;   // cada hija debe implementarlo\n}\nclass Cuadrado extends Figura {\n  constructor(public lado: number) { super(); }\n  area(): number { return this.lado ** 2; }\n}\nconsole.log(new Cuadrado(4).area());", "h": "Calcula el área de un cuadrado desde una clase abstracta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que marca una clase como no instanciable es ___. (8 letras)", "e": "Intentar crear una instancia de una clase abstracta."},
  {"m": "Clases y módulos", "t": "implements", "x": "Palabra que obliga a una clase a cumplir una interfaz.\n\nclass A implements I exige que A tenga todas las propiedades y métodos de I. Una clase puede implementar varias interfaces separadas por comas.", "u": "Garantizar que una clase ofrece ciertos miembros.\n\nQuieres asegurar que la clase Pato tenga el método volar definido en la interfaz Volador.", "p": ["implements obliga a cumplir una interfaz.", "Una clase puede implementar varias interfaces.", "Si falta un miembro, TypeScript marca error."], "c": "interface Volador { volar(): void }\nclass Pato implements Volador {   // debe tener volar()\n  volar(): void { console.log(\"El pato vuela\"); }\n}\nnew Pato().volar();", "h": "Un pato cumple la interfaz Volador.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una clase cumple una interfaz con la palabra ___. (10 letras)", "e": "Olvidar implementar un método exigido por la interfaz."},
  {"m": "Clases y módulos", "t": "Getters y setters", "x": "Métodos de acceso que se usan como si fueran propiedades.\n\nget devuelve un valor calculado y set permite validar antes de guardar. Se usan sin paréntesis, como si fueran propiedades normales.", "u": "Controlar la lectura y escritura de un dato.\n\nQuieres validar que la edad no sea negativa cada vez que se asigna.", "p": ["Un getter se usa como una propiedad, sin paréntesis.", "Un setter puede validar antes de guardar.", "Los getters permiten valores calculados."], "c": "class Persona {\n  private _edad = 0;\n  get edad(): number { return this._edad; }\n  set edad(v: number) { if (v >= 0) this._edad = v; }   // valida\n}\nconst p = new Persona();\np.edad = 20;\nconsole.log(p.edad);", "h": "Guarda la edad solo si no es negativa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que lee un valor como propiedad se declara con ___. (3 letras)", "e": "Llamar a un getter con paréntesis."},
  {"m": "Clases y módulos", "t": "static", "x": "Modificador de miembros que pertenecen a la clase y no a las instancias.\n\nUn miembro static se usa con el nombre de la clase, como Matematica.pi. No necesita new y es común para constantes y funciones auxiliares.", "u": "Compartir datos o utilidades sin crear objetos.\n\nQuieres un contador compartido por todas las instancias, sin crear objetos para leerlo.", "p": ["static pertenece a la clase y no a las instancias.", "Se usa con el nombre de la clase.", "No necesita crear una instancia con new."], "c": "class Contador {\n  static total = 0;   // pertenece a la clase\n  constructor() { Contador.total++; }\n}\nnew Contador(); new Contador();\nconsole.log(Contador.total);", "h": "Cuenta cuántas instancias se crearon.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modificador de miembros de clase compartidos es ___. (6 letras)", "e": "Intentar usar un miembro static desde una instancia."},
  {"m": "Clases y módulos", "t": "Métodos", "x": "Funciones declaradas dentro de una clase.\n\nUn método se declara sin la palabra function y se llama con la instancia, como objeto.metodo(). Puede usar this para leer o modificar las propiedades.", "u": "Dar comportamiento a los objetos.\n\nQuieres que cada objeto Contador sepa incrementarse a sí mismo.", "p": ["Un método es una función dentro de una clase.", "Se llama desde la instancia con un punto.", "Un método puede usar this."], "c": "class Contador {\n  valor = 0;\n  sumar(): void { this.valor++; }   // método\n}\nconst c = new Contador();\nc.sumar(); c.sumar();\nconsole.log(c.valor);", "h": "Incrementa un contador con un método.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un método se llama con el objeto, un punto y el ___. (nombre del método)", "e": "Olvidar los paréntesis al llamar a un método."},
  {"m": "Clases y módulos", "t": "Exportar", "x": "Palabra que hace visible algo de un archivo para otros archivos.\n\nCon export delante de una declaración, otros módulos pueden importarla. Lo que no se exporta queda privado dentro del archivo.", "u": "Compartir funciones, clases y tipos entre archivos.\n\nEscribiste una función en un archivo y quieres usarla desde otro.", "p": ["export hace visible algo para otros archivos.", "Lo no exportado queda privado en el archivo.", "Se puede exportar funciones, clases y tipos."], "c": "// archivo: matematica.ts\n// export function doble(n: number): number { return n * 2; }\nfunction doble(n: number): number { return n * 2; }\nconsole.log(doble(21));", "h": "Define una función que luego podría exportarse.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que comparte algo con otros archivos es ___. (6 letras)", "e": "Olvidar exportar lo que otro archivo necesita."},
  {"m": "Clases y módulos", "t": "Importar", "x": "Palabra que trae a un archivo lo exportado por otro.\n\nimport { nombre } from \"./archivo\" trae lo exportado con ese nombre. Las rutas relativas empiezan con ./ y no se escribe la extensión .ts.", "u": "Usar código de otros archivos o librerías.\n\nQuieres usar en tu archivo una función definida en otro.", "p": ["import trae lo exportado por otro archivo.", "Las llaves indican el nombre exacto exportado.", "Las rutas relativas empiezan con ./."], "c": "// import { doble } from \"./matematica\";   // trae doble desde otro archivo\nconst doble = (n: number): number => n * 2;\nconsole.log(doble(5));", "h": "Usa una función como si se hubiera importado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que trae algo de otro archivo es ___. (6 letras)", "e": "Usar una ruta equivocada en el import."},
  {"m": "Clases y módulos", "t": "export default", "x": "Exportación principal de un archivo que se importa sin llaves.\n\nCada archivo puede tener un solo export default. Al importarlo puedes elegir el nombre que quieras y no se usan llaves.", "u": "Indicar la pieza principal de un módulo.\n\nTu archivo exporta una única clase principal y quieres importarla sin llaves.", "p": ["Cada archivo puede tener un solo export default.", "El export default se importa sin llaves.", "Al importar puedes elegir el nombre libremente."], "c": "// export default class Servicio { ... }\n// import Servicio from \"./servicio\";   // sin llaves\nclass Servicio { nombre = \"principal\"; }\nconsole.log(new Servicio().nombre);", "h": "Define la clase principal de un módulo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La exportación principal de un archivo es export ___. (7 letras)", "e": "Usar llaves al importar un export default."},
  {"m": "Clases y módulos", "t": "import type", "x": "Importación que trae solo tipos y desaparece al compilar.\n\nimport type { Usuario } from \"./tipos\" garantiza que solo se usa como tipo. El compilador lo elimina del JavaScript generado.", "u": "Importar tipos sin añadir código al resultado.\n\nSolo necesitas el tipo Usuario de otro archivo y no quieres traer su código.", "p": ["import type importa solo tipos.", "Se elimina del JavaScript generado.", "Evita importar código que solo sirve para tipar."], "c": "// import type { Usuario } from \"./tipos\";   // solo tipo, sin código\ntype Usuario = { nombre: string };\nconst u: Usuario = { nombre: \"Ana\" };\nconsole.log(u.nombre);", "h": "Usa un tipo como si se hubiera importado solo como tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La importación que trae solo tipos es import ___. (4 letras)", "e": "Importar código completo cuando solo hacía falta un tipo."},
  {"m": "Clases y módulos", "t": "instanceof", "x": "Operador que comprueba si un objeto pertenece a una clase.\n\nx instanceof Clase devuelve true si x fue creado con esa clase o una hija. TypeScript lo usa también para acotar el tipo dentro del if.", "u": "Saber de qué clase es un objeto en tiempo de ejecución.\n\nRecibes un objeto y debes saber si es un Perro antes de pedirle que ladre.", "p": ["instanceof comprueba si un objeto es de una clase.", "Devuelve true también para subclases.", "Acota el tipo dentro del if."], "c": "class Perro { ladrar(): void { console.log(\"guau\"); } }\nconst x: Perro | string = new Perro();\nif (x instanceof Perro) x.ladrar();   // aquí x es Perro", "h": "Comprueba que es un perro antes de ladrar.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que comprueba la clase de un objeto es ___. (10 letras)", "e": "Usar typeof para comprobar clases."},
  {"m": "Clases y módulos", "t": "Polimorfismo", "x": "Capacidad de objetos distintos de responder al mismo método de forma propia.\n\nSi Perro y Gato sobrescriben hablar(), puedes recorrer una lista de Animales llamando hablar() y cada uno responde a su manera sin que el código lo distinga.", "u": "Tratar objetos distintos de manera uniforme.\n\nTienes una lista de animales distintos y quieres que cada uno haga su propio sonido con la misma llamada.", "p": ["El polimorfismo permite que cada clase responda a su manera.", "Se apoya en métodos sobrescritos.", "Permite tratar objetos distintos de forma uniforme."], "c": "class Animal { hablar(): string { return \"...\"; } }\nclass Perro extends Animal { hablar(): string { return \"guau\"; } }\nclass Gato extends Animal { hablar(): string { return \"miau\"; } }\nfor (const a of [new Perro(), new Gato()]) console.log(a.hablar());", "h": "Cada animal responde con su propio sonido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Que objetos distintos respondan al mismo método a su manera es ___. (13 letras)", "e": "Usar muchos if para distinguir clases en lugar de polimorfismo."},
  {"m": "Genéricos y tipos avanzados", "t": "Genéricos", "x": "Tipos con parámetros que se concretan al usarlos.\n\nUn genérico se escribe entre ángulos, como <T>. T funciona como una variable de tipo: se decide al usar la función o la clase, y TypeScript recuerda ese tipo en todo el código.", "u": "Escribir código reutilizable que conserva el tipo.\n\nQuieres una función que devuelva lo mismo que recibe, sea del tipo que sea, sin perder el tipo.", "p": ["Un genérico es un tipo con parámetro, como <T>.", "El tipo concreto se decide al usarlo.", "Los genéricos permiten reutilizar código sin perder el tipo."], "c": "function identidad<T>(valor: T): T {   // T es el tipo variable\n  return valor;\n}\nconsole.log(identidad<number>(5), identidad(\"hola\"));", "h": "Devuelve el mismo valor de cualquier tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro de tipo genérico se escribe entre ___. (<>)", "e": "Usar any en lugar de un genérico y perder el tipo."},
  {"m": "Genéricos y tipos avanzados", "t": "Funciones genéricas", "x": "Funciones con parámetros de tipo propios.\n\nPones <T> después del nombre. TypeScript puede inferir T según el argumento, así que normalmente no hace falta indicarlo al llamar.", "u": "Operar sobre varios tipos con una sola función.\n\nQuieres obtener el primer elemento de cualquier lista, y que el resultado tenga el tipo de sus elementos.", "p": ["Una función genérica declara <T> tras su nombre.", "T suele inferirse del argumento.", "Una sola función sirve para muchos tipos."], "c": "function primero<T>(lista: T[]): T {   // lista de T, devuelve T\n  return lista[0];\n}\nconsole.log(primero([10, 20]), primero([\"a\", \"b\"]));", "h": "Obtiene el primer elemento de listas de distintos tipos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En <T>, la T representa un ___. (tipo)", "e": "Indicar el tipo a mano cuando TypeScript ya lo infiere."},
  {"m": "Genéricos y tipos avanzados", "t": "Interfaces genéricas", "x": "Interfaces que dependen de un tipo parámetro.\n\ninterface Caja<T> { contenido: T } describe una caja de cualquier cosa. Al usarla se indica el tipo: Caja<string> o Caja<number>.", "u": "Describir estructuras que cambian según el tipo de dato.\n\nNecesitas una «caja» que pueda guardar un número en un caso y un texto en otro.", "p": ["Una interfaz genérica recibe un tipo parámetro.", "Al usarla se indica el tipo entre ángulos.", "Sirve para estructuras que contienen distintos tipos."], "c": "interface Caja<T> { contenido: T }   // T se decide al usarla\nconst a: Caja<number> = { contenido: 5 };\nconst b: Caja<string> = { contenido: \"hola\" };\nconsole.log(a.contenido, b.contenido);", "h": "Crea cajas de número y de texto con la misma interfaz.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una interfaz genérica se usa como Caja___. (<tipo>)", "e": "Olvidar indicar el tipo al usar una interfaz genérica."},
  {"m": "Genéricos y tipos avanzados", "t": "Restricciones con extends", "x": "Límite que obliga a que el tipo genérico cumpla cierta forma.\n\n<T extends { length: number }> acepta solo tipos con length. Así dentro de la función puedes usar valor.length con seguridad.", "u": "Usar propiedades concretas dentro de una función genérica.\n\nTu función genérica necesita leer length, así que solo debe aceptar tipos que lo tengan.", "p": ["extends restringe los tipos que acepta un genérico.", "Permite usar propiedades del tipo restringido.", "Un tipo que no cumple la restricción da error."], "c": "function largo<T extends { length: number }>(v: T): number {   // exige length\n  return v.length;\n}\nconsole.log(largo(\"hola\"), largo([1, 2, 3]));", "h": "Mide el largo de textos y de listas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La restricción de un genérico usa la palabra ___. (7 letras)", "e": "Llamar a una función restringida con un tipo que no tiene la propiedad exigida. Un número no tiene la propiedad length."},
  {"m": "Genéricos y tipos avanzados", "t": "keyof", "x": "Operador que obtiene las claves de un tipo como unión de textos.\n\nkeyof Persona da \"nombre\" | \"edad\". Combinado con genéricos permite funciones que reciben un objeto y el nombre de una de sus propiedades.", "u": "Limitar valores a los nombres de propiedades existentes.\n\nQuieres una función que reciba un objeto y el nombre de una de sus propiedades, pero solo nombres válidos.", "p": ["keyof obtiene los nombres de las propiedades de un tipo.", "El resultado es una unión de textos literales.", "Se combina con genéricos para leer propiedades con seguridad."], "c": "type Persona = { nombre: string; edad: number };\ntype Claves = keyof Persona;   // \"nombre\" | \"edad\"\nconst k: Claves = \"edad\";\nconsole.log(k);", "h": "Obtiene las claves válidas de un tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que obtiene las claves de un tipo es ___. (5 letras)", "e": "Escribir un nombre de propiedad que no existe en el tipo."},
  {"m": "Genéricos y tipos avanzados", "t": "typeof en tipos", "x": "Uso de typeof para obtener el tipo de una variable existente.\n\nEn posición de tipo, typeof variable da el tipo de esa variable. Evita duplicar definiciones cuando ya tienes un objeto de ejemplo.", "u": "Reutilizar el tipo de un valor sin escribirlo a mano.\n\nTienes un objeto de configuración y quieres un tipo con su misma forma sin escribirlo otra vez.", "p": ["typeof en un tipo obtiene el tipo de una variable.", "Evita duplicar definiciones de tipo.", "Es útil cuando ya existe un objeto de ejemplo."], "c": "const config = { modo: \"oscuro\", tamano: 14 };\ntype Config = typeof config;   // { modo: string; tamano: number }\nconst otra: Config = { modo: \"claro\", tamano: 12 };\nconsole.log(otra);", "h": "Obtiene el tipo de un objeto existente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para obtener el tipo de una variable existente se usa ___. (6 letras)", "e": "Escribir a mano un tipo que ya se puede obtener de un valor."},
  {"m": "Genéricos y tipos avanzados", "t": "Partial", "x": "Tipo utilitario que vuelve opcionales todas las propiedades.\n\nPartial<T> crea un tipo igual a T pero con todas las propiedades opcionales. Es común en funciones de actualización donde solo llegan algunos campos.", "u": "Representar cambios parciales de un objeto.\n\nAl actualizar un usuario solo llegan algunos campos, no todos.", "p": ["Partial<T> vuelve opcionales todas las propiedades.", "Es útil para actualizaciones parciales.", "Partial no cambia el tipo original."], "c": "type Usuario = { nombre: string; edad: number };\nconst cambios: Partial<Usuario> = { edad: 21 };   // nombre es opcional ahora\nconsole.log(cambios);", "h": "Describe un cambio que solo trae la edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo utilitario que vuelve opcionales todas las propiedades es ___. (7 letras)", "e": "Creer que Partial modifica el tipo original."},
  {"m": "Genéricos y tipos avanzados", "t": "Required", "x": "Tipo utilitario que vuelve obligatorias todas las propiedades.\n\nRequired<T> es lo contrario de Partial: quita el ? de todas las propiedades. Sirve para formularios completos que ya se validaron.", "u": "Exigir que no falte ningún dato opcional.\n\nUn tipo tiene campos opcionales, pero para guardar necesitas que estén todos.", "p": ["Required<T> vuelve obligatorias todas las propiedades.", "Es lo contrario de Partial.", "Quita el ? de las propiedades opcionales."], "c": "type Perfil = { nombre?: string; edad?: number };\nconst completo: Required<Perfil> = { nombre: \"Ana\", edad: 20 };   // todo obligatorio\nconsole.log(completo);", "h": "Exige un perfil con todos sus campos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo que vuelve obligatorias todas las propiedades es ___. (8 letras)", "e": "Olvidar un campo cuando se usa Required."},
  {"m": "Genéricos y tipos avanzados", "t": "Readonly<T>", "x": "Tipo utilitario que vuelve de solo lectura todas las propiedades.\n\nReadonly<T> añade readonly a cada propiedad. Es una protección solo de TypeScript: no impide los cambios en tiempo de ejecución.", "u": "Proteger un objeto completo contra cambios.\n\nQuieres que una configuración completa no pueda modificarse una vez creada.", "p": ["Readonly<T> vuelve de solo lectura todas las propiedades.", "Protege un objeto completo en compilación.", "No impide cambios en tiempo de ejecución."], "c": "type Ajustes = { tema: string; idioma: string };\nconst a: Readonly<Ajustes> = { tema: \"oscuro\", idioma: \"es\" };   // todo de solo lectura\nconsole.log(a);", "h": "Crea unos ajustes de solo lectura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo que vuelve de solo lectura un objeto es ___<T>. (8 letras)", "e": "Creer que Readonly protege el objeto también al ejecutar."},
  {"m": "Genéricos y tipos avanzados", "t": "Pick", "x": "Tipo utilitario que toma solo algunas propiedades de un tipo.\n\nPick<T, \"a\" | \"b\"> crea un tipo con solo esas propiedades. Es útil para mostrar solo ciertos datos de un objeto grande.", "u": "Crear un tipo más pequeño con las propiedades necesarias.\n\nUn tipo Usuario tiene muchos campos y para una lista solo necesitas el nombre.", "p": ["Pick<T, claves> toma solo las claves indicadas.", "El resultado es un tipo más pequeño.", "Las claves se indican como texto o unión de textos."], "c": "type Usuario = { id: number; nombre: string; clave: string };\ntype Resumen = Pick<Usuario, \"id\" | \"nombre\">;   // solo id y nombre\nconst r: Resumen = { id: 1, nombre: \"Ana\" };\nconsole.log(r);", "h": "Crea un resumen con solo id y nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario que elige algunas propiedades es ___. (4 letras)", "e": "Indicar una clave que no existe en el tipo."},
  {"m": "Genéricos y tipos avanzados", "t": "Omit", "x": "Tipo utilitario que quita algunas propiedades de un tipo.\n\nOmit<T, \"clave\"> crea un tipo igual a T sin esas propiedades. Es lo opuesto a Pick y es ideal para no exponer, por ejemplo, contraseñas.", "u": "Excluir datos sensibles o innecesarios.\n\nQuieres devolver un usuario pero sin su contraseña.", "p": ["Omit<T, claves> quita las claves indicadas.", "Es lo opuesto a Pick.", "Sirve para excluir datos sensibles."], "c": "type Usuario = { id: number; nombre: string; clave: string };\ntype Publico = Omit<Usuario, \"clave\">;   // sin clave\nconst p: Publico = { id: 1, nombre: \"Ana\" };\nconsole.log(p);", "h": "Crea un usuario público sin contraseña.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario que quita propiedades de un tipo es ___. (4 letras)", "e": "Confundir Omit con Pick."},
  {"m": "Genéricos y tipos avanzados", "t": "Record", "x": "Tipo utilitario para objetos con claves y valores de un tipo fijo.\n\nRecord<K, V> describe un objeto cuyas claves son de tipo K y sus valores de tipo V. Con claves literales obliga a incluirlas todas.", "u": "Describir diccionarios o tablas de búsqueda.\n\nQuieres guardar el precio de cada fruta usando el nombre como clave.", "p": ["Record<K, V> describe un diccionario tipado.", "Todas las claves son de tipo K.", "Todos los valores son de tipo V."], "c": "const precios: Record<string, number> = { manzana: 1.2, pera: 0.9 };   // clave texto, valor número\nconsole.log(precios[\"pera\"]);", "h": "Guarda el precio de dos frutas por nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario para diccionarios clave-valor es ___. (6 letras)", "e": "Usar un valor del tipo equivocado en un Record."},
  {"m": "Genéricos y tipos avanzados", "t": "Tipos condicionales", "x": "Tipos que eligen una alternativa según una condición con extends.\n\nLa forma es T extends U ? X : Y: si T encaja en U, el tipo es X; si no, es Y. Es como un if, pero entre tipos.", "u": "Calcular un tipo a partir de otro.\n\nQuieres un tipo que sea «sí» si T es texto y «no» en cualquier otro caso.", "p": ["Un tipo condicional elige un tipo según una condición.", "Se escribe con extends, ? y :.", "Funciona como un if entre tipos."], "c": "type EsTexto<T> = T extends string ? \"sí\" : \"no\";   // if entre tipos\nconst a: EsTexto<string> = \"sí\";\nconst b: EsTexto<number> = \"no\";\nconsole.log(a, b);", "h": "Decide un tipo según sea texto o no.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En un tipo condicional, la condición usa la palabra ___. (7 letras)", "e": "Confundir la condición de tipos con un if de valores."},
  {"m": "Genéricos y tipos avanzados", "t": "Tipos mapeados", "x": "Tipos que transforman cada propiedad de otro tipo.\n\nSe escribe { [K in keyof T]: ... } y recorre cada propiedad. Los utilitarios Partial y Readonly se construyen así.", "u": "Crear variantes de un tipo aplicando una regla a todas sus propiedades.\n\nQuieres una versión de un tipo donde todas las propiedades sean booleanas.", "p": ["Un tipo mapeado recorre las propiedades de un tipo.", "Se escribe con [K in keyof T].", "Partial y Readonly son tipos mapeados."], "c": "type Persona = { nombre: string; edad: number };\ntype Banderas = { [K in keyof Persona]: boolean };   // cada propiedad pasa a boolean\nconst b: Banderas = { nombre: true, edad: false };\nconsole.log(b);", "h": "Convierte todas las propiedades de un tipo en booleanas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En un tipo mapeado se recorre con [K ___ keyof T]. (2 letras)", "e": "Olvidar keyof y recorrer algo que no son claves."},
  {"m": "Genéricos y tipos avanzados", "t": "Uniones discriminadas", "x": "Uniones de objetos que comparten una propiedad literal distintiva.\n\nCada variante tiene una propiedad como tipo: \"circulo\" o tipo: \"cuadrado\". Un switch sobre esa propiedad permite a TypeScript saber qué campos existen en cada caso.", "u": "Distinguir con seguridad entre variantes de un mismo dato.\n\nUna figura puede ser círculo (radio) o cuadrado (lado) y quieres tratar cada una con seguridad.", "p": ["Una unión discriminada comparte una propiedad literal.", "El switch sobre esa propiedad acota el tipo.", "Permite saber qué campos existen en cada variante."], "c": "type Figura = { tipo: \"circulo\"; radio: number } | { tipo: \"cuadrado\"; lado: number };\nfunction area(f: Figura): number {\n  switch (f.tipo) {   // acota según tipo\n    case \"circulo\": return Math.PI * f.radio ** 2;\n    case \"cuadrado\": return f.lado ** 2;\n  }\n}\nconsole.log(area({ tipo: \"cuadrado\", lado: 3 }));", "h": "Calcula el área de una figura que puede ser círculo o cuadrado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad compartida que identifica cada variante se llama ___. (13 letras: discriminante)", "e": "Olvidar la propiedad que distingue las variantes."},
  {"m": "Genéricos y tipos avanzados", "t": "Guardas de tipo", "x": "Funciones que indican a TypeScript qué tipo tiene un valor.\n\nUna guarda devuelve un predicado como valor is string. Si devuelve true, TypeScript trata el valor como ese tipo en el bloque siguiente.", "u": "Acotar tipos con una comprobación propia.\n\nQuieres una función reutilizable que compruebe si un valor es un texto y avise a TypeScript.", "p": ["Una guarda de tipo usa un predicado como valor is Tipo.", "Si devuelve true, el valor se acota a ese tipo.", "Permite crear comprobaciones propias reutilizables."], "c": "function esTexto(v: unknown): v is string {   // predicado de tipo\n  return typeof v === \"string\";\n}\nconst x: unknown = \"hola\";\nif (esTexto(x)) console.log(x.toUpperCase());", "h": "Comprueba con una guarda que un valor es texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El predicado de una guarda se escribe v ___ string. (2 letras)", "e": "Devolver boolean normal en lugar de un predicado y perder el acotado."},
  {"m": "Genéricos y tipos avanzados", "t": "never", "x": "Tipo de valores que nunca ocurren.\n\nUna función que siempre lanza un error devuelve never. También se usa al final de un switch para que TypeScript avise si falta un caso.", "u": "Marcar código inalcanzable o comprobar que se cubrieron todos los casos.\n\nTu función siempre lanza una excepción y nunca termina con normalidad.", "p": ["never representa valores que nunca ocurren.", "Una función que siempre lanza error devuelve never.", "Sirve para detectar casos sin cubrir."], "c": "function fallar(msg: string): never {   // nunca devuelve\n  throw new Error(msg);\n}\ntry { fallar(\"algo salió mal\"); } catch (e) { console.log(\"capturado\"); }", "h": "Lanza un error con una función que devuelve never.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de lo que nunca ocurre es ___. (5 letras)", "e": "Usar never donde sí hay un valor de retorno."},
  {"m": "Genéricos y tipos avanzados", "t": "Firmas de índice", "x": "Tipo para objetos con claves que no se conocen de antemano.\n\nSe escribe { [clave: string]: number }. Cualquier clave de texto es válida y su valor debe ser número. Es el equivalente a Record<string, number>.", "u": "Describir objetos usados como diccionarios.\n\nNo sabes los nombres de las claves, pero todos sus valores son números.", "p": ["Una firma de índice describe claves desconocidas.", "Se escribe con [clave: string]: tipo.", "Es equivalente a Record<string, tipo>."], "c": "const notas: { [alumno: string]: number } = {};   // claves libres\nnotas[\"Ana\"] = 9;\nnotas[\"Luis\"] = 7;\nconsole.log(notas);", "h": "Guarda notas por nombre de alumno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una firma de índice se escribe [clave: ___]: tipo. (string)", "e": "Usar un valor del tipo equivocado en la firma de índice."},
  {"m": "Genéricos y tipos avanzados", "t": "Promise<T>", "x": "Tipo de una operación asíncrona que devolverá un valor de tipo T.\n\nPromise<number> promete un número en el futuro. Se consume con then o con await dentro de una función async.", "u": "Tipar resultados que llegan más tarde.\n\nUna función tarda en responder y devolverá un número más adelante.", "p": ["Promise<T> representa un valor que llegará después.", "Se consume con then o con await.", "T es el tipo del valor prometido."], "c": "function esperar(): Promise<number> {   // promete un número\n  return Promise.resolve(42);\n}\nesperar().then((n) => console.log(n));", "h": "Obtiene un número prometido y lo muestra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de un valor que llegará después es ___<T>. (7 letras)", "e": "Usar el valor de una Promise sin esperar a que se resuelva."},
  {"m": "Genéricos y tipos avanzados", "t": "Clases genéricas", "x": "Clases que dependen de un tipo parámetro.\n\nclass Pila<T> guarda elementos de tipo T. Al crearla se decide el tipo: new Pila<number>(). Así una misma clase sirve para números, textos u objetos con seguridad.", "u": "Crear estructuras de datos reutilizables para cualquier tipo.\n\nQuieres una pila que guarde solo números en un caso y solo textos en otro, con la misma clase.", "p": ["Una clase genérica recibe un tipo parámetro como <T>.", "El tipo se decide al crear la instancia.", "Una misma clase genérica sirve para muchos tipos."], "c": "class Pila<T> {\n  private items: T[] = [];\n  apilar(x: T): void { this.items.push(x); }   // solo acepta T\n  total(): number { return this.items.length; }\n}\nconst p = new Pila<number>();\np.apilar(5);\nconsole.log(p.total());", "h": "Crea una pila de números y cuenta sus elementos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una clase genérica se crea como new Pila___. (<number>)", "e": "Mezclar tipos distintos en una clase genérica ya definida para un tipo."},
  {"m": "TypeScript profesional", "t": "tsconfig.json", "x": "Archivo de configuración del compilador de TypeScript.\n\ntsconfig.json indica carpetas, versión de JavaScript de salida y reglas de revisión. Se crea con tsc --init y se comparte con todo el equipo.", "u": "Definir cómo se compila el proyecto.\n\nTu equipo necesita que todos compilen con las mismas reglas.", "p": ["tsconfig.json configura el compilador.", "Se crea con tsc --init.", "Define la salida y las reglas de revisión."], "c": "// tsconfig.json:  { \"compilerOptions\": { \"target\": \"ES2020\", \"strict\": true } }\nconsole.log(\"Configuración compartida por todo el equipo\");", "h": "Muestra un mensaje sobre la configuración compartida.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo de configuración de TypeScript se llama ___.json. (8 letras)", "e": "Compilar cada archivo con opciones distintas en cada equipo."},
  {"m": "TypeScript profesional", "t": "Modo strict", "x": "Opción que activa las comprobaciones más estrictas de tipos.\n\n\"strict\": true activa varias reglas a la vez, como no permitir null sin declararlo y no aceptar any implícito. Es la configuración recomendada para proyectos nuevos.", "u": "Detectar más errores antes de ejecutar.\n\nQuieres que el compilador sea lo más exigente posible desde el inicio de un proyecto.", "p": ["strict activa las comprobaciones más estrictas.", "Impide null o undefined sin declararlos.", "Es recomendable en proyectos nuevos."], "c": "// \"strict\": true  en tsconfig.json\nlet nombre: string = \"Ana\";   // con strict, nunca puede ser null sin declararlo\nconsole.log(nombre);", "h": "Muestra una variable que con strict nunca será null.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción que activa las comprobaciones estrictas es ___. (6 letras)", "e": "Desactivar strict para evitar los errores en vez de corregirlos."},
  {"m": "TypeScript profesional", "t": "async y await", "x": "Sintaxis para escribir código asíncrono que se lee como secuencial.\n\nUna función async siempre devuelve una Promise. Dentro de ella, await pausa hasta que otra Promise se resuelva y entrega su valor.", "u": "Esperar resultados sin anidar callbacks.\n\nNecesitas esperar una respuesta antes de seguir con la siguiente línea, sin callbacks anidados.", "p": ["async hace que una función devuelva una Promise.", "await espera el resultado de una Promise.", "await solo se usa dentro de funciones async."], "c": "async function obtener(): Promise<number> { return 7; }\nasync function main() {\n  const n = await obtener();   // espera el valor\n  console.log(\"Recibido:\", n);\n}\nmain();", "h": "Espera un número de una función asíncrona y lo muestra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que espera una Promise es ___. (5 letras)", "e": "Usar await fuera de una función async. await solo puede usarse dentro de una función async."},
  {"m": "TypeScript profesional", "t": "try y catch", "x": "Estructura que captura errores sin detener el programa.\n\nEl código que puede fallar va en try. Si lanza un error, la ejecución salta a catch y allí se puede mostrar un mensaje o recuperar. finally se ejecuta siempre.", "u": "Manejar fallos de forma controlada.\n\nUn cálculo puede lanzar un error y no quieres que se caiga todo el programa.", "p": ["try contiene el código que puede fallar.", "catch recibe el error y permite manejarlo.", "finally se ejecuta siempre."], "c": "try {\n  throw new Error(\"fallo simulado\");   // código que puede fallar\n} catch (e) {\n  console.log(\"Error controlado\");\n} finally {\n  console.log(\"Esto se ejecuta siempre\");\n}", "h": "Captura un error simulado sin romper el programa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bloque que recibe el error es ___. (5 letras)", "e": "Dejar el catch vacío y esconder los errores."},
  {"m": "TypeScript profesional", "t": "Errores tipados", "x": "Manejo de catch donde el error se trata como unknown.\n\nCon strict, el error de catch es unknown porque en JavaScript se puede lanzar cualquier cosa. Comprueba con instanceof Error antes de leer su message.", "u": "No asumir qué es lo que se lanzó.\n\nDentro de catch quieres leer el mensaje del error con seguridad de tipos.", "p": ["Con strict el error de catch es unknown.", "Hay que comprobar que es un Error antes de leer message.", "En JavaScript se puede lanzar cualquier valor."], "c": "try {\n  throw new Error(\"algo falló\");\n} catch (e: unknown) {\n  if (e instanceof Error) console.log(e.message);   // comprueba antes de usar\n}", "h": "Muestra el mensaje solo si es un Error.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Antes de leer message se comprueba con ___ Error. (instanceof)", "e": "Leer e.message sin comprobar que e es un Error."},
  {"m": "TypeScript profesional", "t": "Tipar respuestas JSON", "x": "Definir la forma esperada de los datos que llegan de una API.\n\nLos datos externos llegan sin tipo. Defines una interfaz con la forma esperada y la usas para tipar el resultado. TypeScript no valida el JSON real: conviene comprobarlo.", "u": "Trabajar con datos externos con ayuda del editor.\n\nRecibes un JSON de una API con id y nombre y quieres autocompletado al usarlo.", "p": ["Una interfaz describe la forma esperada del JSON.", "TypeScript no valida el JSON en tiempo de ejecución.", "Conviene comprobar los datos externos."], "c": "interface Usuario { id: number; nombre: string }\nconst texto = '{\"id\":1,\"nombre\":\"Ana\"}';\nconst u = JSON.parse(texto) as Usuario;   // afirma la forma esperada\nconsole.log(u.nombre);", "h": "Convierte un JSON de texto en un usuario tipado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que convierte texto JSON en objeto es JSON.___. (5 letras)", "e": "Creer que as Usuario valida el contenido real del JSON."},
  {"m": "TypeScript profesional", "t": "Archivos de declaración", "x": "Archivos .d.ts que describen los tipos de código JavaScript.\n\nUn archivo .d.ts contiene solo declaraciones de tipos, sin código. Permite que el editor entienda librerías escritas en JavaScript puro.", "u": "Usar librerías de JavaScript con tipos.\n\nUsas una librería escrita en JavaScript y quieres autocompletado y tipos.", "p": ["Un archivo .d.ts contiene solo declaraciones de tipos.", "Permite tipar librerías escritas en JavaScript.", "No contiene código ejecutable."], "c": "// libreria.d.ts:  declare function saludar(nombre: string): string;\ndeclare const version: string;\nconsole.log(\"Los .d.ts solo describen tipos\");", "h": "Muestra un mensaje sobre los archivos de declaración.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las declaraciones de tipos viven en archivos ___. (.d.ts)", "e": "Esperar que un .d.ts contenga código que se ejecuta."},
  {"m": "TypeScript profesional", "t": "Paquetes @types", "x": "Paquetes con los tipos de librerías que no los incluyen.\n\nSe instalan como npm install -D @types/nombre. Así librerías populares como lodash o node ganan tipos sin cambiar su código.", "u": "Añadir tipos a librerías de JavaScript desde npm.\n\nUna librería popular de JavaScript no trae tipos y el editor no la entiende.", "p": ["@types agrupa tipos de librerías de la comunidad.", "Se instalan con npm como dependencia de desarrollo.", "Añaden tipos sin cambiar el código de la librería."], "c": "// npm install -D @types/node   // tipos de Node.js\nconsole.log(\"Los @types añaden tipos a librerías existentes\");", "h": "Muestra un mensaje sobre los paquetes @types.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los tipos de la comunidad se instalan con el prefijo ___/. (@types)", "e": "Instalar @types de una librería que ya trae sus propios tipos."},
  {"m": "TypeScript profesional", "t": "as const", "x": "Aserción que fija un valor como literal e inmutable.\n\nCon as const, los valores no se ensanchan a string o number: se conservan como literales y todo queda readonly. Muy útil para listas fijas de opciones.", "u": "Obtener tipos literales exactos de un objeto o lista.\n\nTienes una lista fija de colores y quieres que su tipo sea la unión exacta de esos textos.", "p": ["as const fija los valores como literales.", "Todo el valor queda como readonly.", "Sirve para listas fijas de opciones."], "c": "const colores = [\"rojo\", \"verde\", \"azul\"] as const;   // tipos literales\ntype Color = (typeof colores)[number];\nconst c: Color = \"rojo\";\nconsole.log(c);", "h": "Obtiene un tipo con los colores permitidos de una lista fija.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La aserción que fija un valor literal e inmutable es as ___. (5 letras)", "e": "Intentar modificar un array declarado con as const."},
  {"m": "TypeScript profesional", "t": "satisfies", "x": "Operador que comprueba un valor contra un tipo sin ensanchar su tipo.\n\nvalor satisfies Tipo verifica que el valor cumple el tipo pero conserva el tipo exacto del valor. A diferencia de una anotación, no lo ensancha.", "u": "Validar la forma de un objeto sin perder los tipos específicos.\n\nQuieres comprobar que un objeto cumple un tipo pero conservar los tipos exactos de sus propiedades.", "p": ["satisfies valida un valor contra un tipo.", "Conserva el tipo exacto del valor.", "Evita ensanchar el tipo como haría una anotación."], "c": "type Paleta = Record<string, string | number[]>;\nconst p = { rojo: [255, 0, 0], verde: \"#0f0\" } satisfies Paleta;   // valida sin ensanchar\nconsole.log(p.rojo.length);", "h": "Valida una paleta de colores conservando sus tipos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que valida sin ensanchar el tipo es ___. (9 letras)", "e": "Usar una anotación y perder los tipos específicos."},
  {"m": "TypeScript profesional", "t": "Operador !", "x": "Aserción de no nulo que afirma que un valor no es null ni undefined.\n\nvalor! le dice al compilador que confíe en ti. Si el valor sí es null, el programa fallará al ejecutar. Úsalo solo cuando estés completamente seguro.", "u": "Indicar que sabes que existe un valor que TypeScript duda.\n\nEstás seguro de que un valor existe pero TypeScript cree que puede ser null.", "p": ["El operador ! afirma que el valor no es null ni undefined.", "Si te equivocas, el error ocurre al ejecutar.", "Solo conviene usarlo cuando estás seguro."], "c": "const nombres: string[] = [\"Ana\", \"Luis\"];\nconst primero = nombres.find((n) => n === \"Ana\")!;   // afirma que existe\nconsole.log(primero.length);", "h": "Busca un nombre y afirma que existe.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La aserción de no nulo se escribe con el signo ___. (!)", "e": "Usar ! para silenciar un posible null que sí puede ocurrir."},
  {"m": "TypeScript profesional", "t": "ReturnType", "x": "Tipo utilitario que obtiene el tipo que devuelve una función.\n\nReturnType<typeof funcion> extrae el tipo de lo que devuelve esa función. Si cambias la función, el tipo se actualiza solo.", "u": "Reutilizar el tipo de retorno sin repetirlo.\n\nQuieres un tipo igual al resultado de una función sin escribirlo a mano.", "p": ["ReturnType obtiene el tipo de retorno de una función.", "Se usa junto con typeof.", "El tipo se actualiza si cambia la función."], "c": "function crearUsuario() { return { id: 1, nombre: \"Ana\" }; }\ntype Usuario = ReturnType<typeof crearUsuario>;   // { id: number; nombre: string }\nconst u: Usuario = crearUsuario();\nconsole.log(u);", "h": "Obtiene el tipo del resultado de una función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario que obtiene el tipo de retorno es ___Type. (6 letras)", "e": "Escribir a mano el tipo y olvidar actualizarlo al cambiar la función."},
  {"m": "TypeScript profesional", "t": "Parameters", "x": "Tipo utilitario que obtiene los tipos de los parámetros de una función.\n\nParameters<typeof funcion> devuelve una tupla con los tipos de los parámetros, en orden. Es útil para envolver funciones sin repetir su firma.", "u": "Reutilizar la firma de una función.\n\nQuieres envolver una función y que tu envoltorio acepte exactamente los mismos parámetros.", "p": ["Parameters obtiene los tipos de los parámetros.", "Devuelve una tupla con los tipos en orden.", "Sirve para envolver funciones sin repetir la firma."], "c": "function sumar(a: number, b: number): number { return a + b; }\ntype Args = Parameters<typeof sumar>;   // [a: number, b: number]\nconst args: Args = [2, 3];\nconsole.log(sumar(...args));", "h": "Reutiliza los parámetros de una función para llamarla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario que obtiene los tipos de los parámetros es ___. (10 letras)", "e": "Cambiar la función y no actualizar el tipo de sus parámetros."},
  {"m": "TypeScript profesional", "t": "Awaited", "x": "Tipo utilitario que obtiene el tipo resultante de una Promise.\n\nAwaited<Promise<number>> da number. Resuelve también promesas anidadas. Es útil con ReturnType cuando una función async devuelve una Promise.", "u": "Saber qué tipo entrega un await.\n\nUna función async devuelve Promise<Usuario> y quieres el tipo Usuario solo.", "p": ["Awaited obtiene el tipo que entrega una Promise.", "Resuelve promesas anidadas.", "Se combina con ReturnType en funciones async."], "c": "async function cargar() { return { id: 1 }; }\ntype Datos = Awaited<ReturnType<typeof cargar>>;   // { id: number }\nconst d: Datos = { id: 2 };\nconsole.log(d);", "h": "Obtiene el tipo que entrega una función async.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El utilitario que quita la Promise del tipo es ___. (7 letras)", "e": "Usar Promise<T> donde en realidad se necesita T."},
  {"m": "TypeScript profesional", "t": "ESLint", "x": "Herramienta que revisa el estilo y los problemas del código.\n\nESLint encuentra errores y malas prácticas más allá de los tipos, como variables sin usar o any innecesarios. Con typescript-eslint entiende TypeScript.", "u": "Mantener un código limpio y coherente.\n\nTu equipo quiere que todo el código siga las mismas reglas de estilo y evite malas prácticas.", "p": ["ESLint revisa el estilo y los problemas del código.", "Detecta malas prácticas más allá de los tipos.", "typescript-eslint lo adapta a TypeScript."], "c": "// npm install -D eslint typescript-eslint\nconst sinUsar = 1;   // ESLint avisaría: variable sin usar\nconsole.log(\"ESLint revisa el estilo\");", "h": "Muestra un mensaje sobre la revisión con ESLint.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta que revisa el estilo del código es ___. (6 letras)", "e": "Ignorar las advertencias de ESLint."},
  {"m": "TypeScript profesional", "t": "Pruebas", "x": "Código que comprueba automáticamente que tu programa funciona.\n\nUna prueba llama a una función con datos conocidos y comprueba el resultado esperado. Herramientas como Jest o Vitest las ejecutan en segundos.", "u": "Detectar errores al cambiar el código.\n\nCada vez que cambias código temes romper algo ya hecho.", "p": ["Una prueba comprueba automáticamente un comportamiento.", "Compara el resultado real con el esperado.", "Jest y Vitest ejecutan pruebas."], "c": "function sumar(a: number, b: number): number { return a + b; }\nconst esperado = 5;\nconsole.log(sumar(2, 3) === esperado ? \"prueba superada\" : \"prueba fallida\");", "h": "Comprueba que la suma da el valor esperado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El código que comprueba automáticamente tu programa es una ___. (6 letras)", "e": "Cambiar el código sin ninguna prueba que lo respalde."},
  {"m": "TypeScript profesional", "t": "Migrar JavaScript a TypeScript", "x": "Proceso de pasar poco a poco un proyecto JavaScript a TypeScript.\n\nSe activa allowJs, se renombran archivos de .js a .ts de uno en uno y se añaden tipos progresivamente. No hace falta convertir todo de golpe.", "u": "Ganar seguridad de tipos sin reescribir todo.\n\nTienes un proyecto JavaScript grande y no puedes reescribirlo de una vez.", "p": ["Migrar es pasar un proyecto de JavaScript a TypeScript.", "Se puede hacer poco a poco.", "allowJs permite mezclar archivos .js y .ts."], "c": "// 1. allowJs: true   2. renombrar un archivo .js a .ts   3. añadir tipos poco a poco\nlet total: number = 0;\nconsole.log(total);", "h": "Muestra un valor ya tipado como primer paso de migración.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción que permite mezclar archivos .js y .ts es ___. (allowJs)", "e": "Intentar convertir un proyecto grande de una sola vez."},
  {"m": "TypeScript profesional", "t": "Evitar any", "x": "Buena práctica de reemplazar any por tipos precisos.\n\nCada any deja un hueco en la revisión. Prefiere unknown con comprobación, genéricos o interfaces. Activa la regla no-explicit-any para que el equipo lo evite.", "u": "Mantener la protección de TypeScript.\n\nTu código está lleno de any y los errores aparecen al ejecutar.", "p": ["Cada any elimina la protección del tipado.", "unknown con comprobación es una alternativa más segura.", "La regla no-explicit-any ayuda a evitar any."], "c": "function mostrar(valor: unknown): void {   // mejor unknown que any\n  if (typeof valor === \"string\") console.log(valor);\n  else console.log(\"no es texto\");\n}\nmostrar(\"hola\");\nmostrar(5);", "h": "Trata distintos valores sin usar any.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La alternativa segura a any es ___. (7 letras)", "e": "Usar any por comodidad cada vez que aparece un error de tipos."},
  {"m": "TypeScript profesional", "t": "Eventos del DOM", "x": "Tipos que describen los eventos y elementos de una página web.\n\nElementos como HTMLInputElement y eventos como MouseEvent dan autocompletado. Algunas funciones, como querySelector, pueden devolver null y hay que comprobarlo.", "u": "Escribir código del navegador con ayuda del editor.\n\nQuieres leer el valor de un campo de texto de la página con autocompletado y seguridad.", "p": ["TypeScript incluye tipos para elementos y eventos del DOM.", "querySelector puede devolver null.", "Los tipos del DOM dan autocompletado."], "c": "// const campo = document.querySelector(\"input\") as HTMLInputElement;\n// console.log(campo.value);\nconsole.log(\"Los tipos del DOM, como HTMLInputElement, dan autocompletado\");", "h": "Muestra un mensaje sobre los tipos del DOM.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de un campo de texto del DOM es HTML___Element. (Input)", "e": "Usar el resultado de querySelector sin comprobar que no sea null."},
  {"m": "TypeScript profesional", "t": "Compilar para producción", "x": "Generar el JavaScript final optimizado para publicar la aplicación.\n\nEn producción se ejecuta el JavaScript generado, no los .ts. Se compila con tsc o con una herramienta como esbuild o Vite, y se publica la carpeta de salida.", "u": "Entregar un resultado listo para ejecutar sin TypeScript.\n\nTu aplicación ya está lista y debes publicarla.", "p": ["En producción se ejecuta el JavaScript generado.", "Se compila con tsc o herramientas como Vite.", "Se publica la carpeta de salida, no los archivos .ts."], "c": "// npm run build   -> compila a la carpeta dist/\nconsole.log(\"Se publica dist/, no el código .ts\");", "h": "Muestra un mensaje sobre qué se publica en producción.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En producción se publica el código ___. (JavaScript)", "e": "Subir al servidor los archivos .ts sin compilar."}
];
